layer.fontFaces:
@font-face { font-display: swap; font-family: "latin modern roman"; font-style: normal; font-weight: 700; src: url("{{assets}}/hugo-texify3_demo/lmroman-bold.woff"); }
@font-face { font-display: swap; font-family: "latin modern roman"; font-style: italic; font-weight: 700; src: url("{{assets}}/hugo-texify3_demo/lmroman-bolditalic.woff"); }
@font-face { font-display: swap; font-family: "latin modern roman"; font-style: italic; font-weight: 400; src: url("{{assets}}/hugo-texify3_demo/lmroman-italic.woff"); }
@font-face { font-display: swap; font-family: "latin modern roman"; font-style: normal; font-weight: 400; src: url("{{assets}}/hugo-texify3_demo/lmroman-normal.woff"); }

layer.css:
[data-ryt="footer"] { color: rgb(124, 111, 100); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 40px; font-weight: 700; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: rgb(60, 56, 54); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 19.2px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(60, 56, 54); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; position: relative }
[data-ryt="button"] { color: var(--ryt-text); background-color: var(--ryt-bg); border-radius: 4px; font-family: Arial; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 8px; padding-bottom: 8px; padding-left: 8px; transition: opacity 0.3s }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { color: #458598 }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #458598 }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #458598 }
[data-ryt="button"]:hover { color: #3c3836 }
[data-ryt="nav"] a::after { content: ""; display: block; position: absolute; width: 100%; height: 2px; color: rgb(60, 56, 54); background-color: rgb(60, 56, 54); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 19.2px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(60, 56, 54); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: transform 0.25s ease-out; -webkit-text-fill-color: rgb(60, 56, 54); bottom: 0px; left: 0px }
[data-ryt="nav"] a:hover { color: #458598; color: #3c3836 }
